   IF actual.definition IS DISTINCT FROM item->>'definition' OR NOT actual.valid OR NOT actual.ready THEN
     RAISE EXCEPTION 'Schema drift: index % definition/validity differs',item->>'name';
   END IF;
 END LOOP;
